:root {
  --color-bg: #1a1a2e;
  --color-card: #16213e;
  --color-accent: #e94560;
  --color-text: #eaeaea;
  --color-highlight: #0f3460;
  --font-system: system-ui, 'Segoe UI', Roboto, sans-serif;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--color-bg);
  font-family: var(--font-system);
  font-size: 16px;
  color: var(--color-text);
  padding: 16px;
}

.card {
  background: var(--color-card);
  border: 4px solid var(--color-highlight);
  border-radius: 12px;
  padding: 24px;
  width: 100%;
  max-width: 400px;
  box-shadow: 0 8px 0 var(--color-highlight);
}

h1 {
  margin: 0 0 16px;
  font-size: 1.5rem;
  text-align: center;
  color: var(--color-accent);
  letter-spacing: 2px;
  text-transform: uppercase;
}

.elevator {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.car {
  background: #0a0a1a;
  border: 3px solid var(--color-highlight);
  border-radius: 8px;
  height: 80px;
  position: relative;
  overflow: hidden;
}

.doors {
  display: flex;
  height: 100%;
  width: 100%;
  position: absolute;
  top: 0;
  left: 0;
}

.door {
  flex: 1;
  background: var(--color-highlight);
  transition: transform 0.3s ease;
  border: 1px solid #0a0a1a;
}

.door.left { transform-origin: left; }
.door.right { transform-origin: right; }

.doors.open .door.left { transform: scaleX(0); }
.doors.open .door.right { transform: scaleX(0); }

.readout {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: #0a0a1a;
  border: 3px solid var(--color-highlight);
  border-radius: 8px;
  padding: 12px 16px;
}

.floor-display {
  font-size: 2rem;
  font-weight: bold;
  color: var(--color-accent);
  font-family: monospace;
}

.direction {
  font-size: 1rem;
  color: var(--color-text);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.panel {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

.panel button {
  background: var(--color-highlight);
  color: var(--color-text);
  border: 3px solid var(--color-accent);
  border-radius: 8px;
  padding: 12px 0;
  font-size: 1.2rem;
  font-family: monospace;
  font-weight: bold;
  cursor: pointer;
  transition: background 0.1s, transform 0.1s;
  min-height: 48px;
}

.panel button:hover {
  background: var(--color-accent);
  color: var(--color-card);
}

.panel button:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.panel button:active {
  transform: translateY(2px);
}

.panel button.queued {
  background: var(--color-accent);
  color: var(--color-card);
  border-color: var(--color-text);
}

.hint {
  margin: 16px 0 0;
  font-size: 0.9rem;
  text-align: center;
  color: #aaa;
}

[hidden] { display: none !important; }

@media (max-width: 360px) {
  .card { padding: 16px; }
  .panel { gap: 8px; }
  .panel button { font-size: 1rem; padding: 8px 0; }
  .floor-display { font-size: 1.5rem; }
}

(function() {
  'use strict';

  const MIN_FLOOR = 1;
  const MAX_FLOOR = 6;
  const TICK_MS = 1000;

  const state = {
    currentFloor: 1,
    direction: 'idle', // 'up', 'down', 'idle'
    queue: new Set(),
    doorsOpen: false,
    moving: false
  };

  const floorDisplay = document.getElementById('floorDisplay');
  const directionEl = document.getElementById('direction');
  const panel = document.getElementById('panel');
  const doors = document.getElementById('doors');

  // Build floor buttons (6 to 1, top to bottom like a real panel)
  for (let f = MAX_FLOOR; f >= MIN_FLOOR; f--) {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.textContent = f;
    btn.setAttribute('aria-label', 'Floor ' + f);
    btn.dataset.floor = f;
    btn.addEventListener('click', () => requestFloor(f));
    panel.appendChild(btn);
  }

  function requestFloor(floor) {
    if (floor === state.currentFloor) {
      // Already here: open doors if idle
      if (!state.moving && !state.doorsOpen) {
        openDoors();
        setTimeout(closeDoors, 800);
      }
      return;
    }
    state.queue.add(floor);
    render();
    if (!state.moving) {
      startMoving();
    }
  }

  function getNextTarget() {
    if (state.queue.size === 0) return null;
    const floors = Array.from(state.queue);
    // Choose nearest floor in current direction preference
    if (state.direction === 'up') {
      const above = floors.filter(f => f > state.currentFloor).sort((a,b) => a-b);
      if (above.length) return above[0];
      const below = floors.filter(f => f < state.currentFloor).sort((a,b) => b-a);
      if (below.length) return below[0];
    } else if (state.direction === 'down') {
      const below = floors.filter(f => f < state.currentFloor).sort((a,b) => b-a);
      if (below.length) return below[0];
      const above = floors.filter(f => f > state.currentFloor).sort((a,b) => a-b);
      if (above.length) return above[0];
    } else {
      // idle: nearest
      floors.sort((a,b) => Math.abs(a - state.currentFloor) - Math.abs(b - state.currentFloor));
      return floors[0];
    }
    return null;
  }

  function startMoving() {
    if (state.moving) return;
    const target = getNextTarget();
    if (target === null) {
      state.direction = 'idle';
      render();
      return;
    }
    state.moving = true;
    state.direction = target > state.currentFloor ? 'up' : 'down';
    render();
    // First move happens after one second
    setTimeout(tick, TICK_MS);
  }

  function tick() {
    if (!state.moving) return;
    const target = getNextTarget();
    if (target === null) {
      state.moving = false;
      state.direction = 'idle';
      render();
      return;
    }

    // Update direction based on target
    if (target > state.currentFloor) state.direction = 'up';
    else if (target < state.currentFloor) state.direction = 'down';

    // Move one floor
    if (state.direction === 'up') state.currentFloor++;
    else if (state.direction === 'down') state.currentFloor--;

    render();

    // Check arrival
    if (state.queue.has(state.currentFloor)) {
      state.queue.delete(state.currentFloor);
      state.moving = false;
      openDoors();
      render();
      setTimeout(() => {
        closeDoors();
        // After doors close, continue if queue remains
        setTimeout(() => {
          if (state.queue.size > 0) {
            startMoving();
          } else {
            state.direction = 'idle';
            render();
          }
        }, 300);
      }, 800);
    } else {
      setTimeout(tick, TICK_MS);
    }
  }

  function openDoors() {
    state.doorsOpen = true;
    doors.classList.add('open');
  }

  function closeDoors() {
    state.doorsOpen = false;
    doors.classList.remove('open');
  }

  function render() {
    floorDisplay.textContent = state.currentFloor;
    directionEl.textContent = state.direction === 'idle' ? 'Idle' : (state.direction === 'up' ? '▲ Up' : '▼ Down');

    // Update button states
    const buttons = panel.querySelectorAll('button');
    buttons.forEach(btn => {
      const f = Number(btn.dataset.floor);
      if (state.queue.has(f)) {
        btn.classList.add('queued');
        btn.setAttribute('aria-pressed', 'true');
      } else {
        btn.classList.remove('queued');
        btn.setAttribute('aria-pressed', 'false');
      }
    });
  }

  // Initial render
  render();
})();
